import com.webcommander.sdk.client.ApiResponse;
import java.util.List;
import java.util.Map;

ApiResponse response = client.email().sendEmail(Map.of(
        "recipients", List.of("customer@example.com"), "cc", List.of("orders@example.com"),
        "subject", "Your order has shipped", "htmlContent", "<p>Your order is on its way.</p>",
        "contentType", "text/html"));
Map<?, ?> body = (Map<?, ?>) response.getMap();
System.out.println(body.get("status") + " " + body.get("accepted") + " " + body.get("rejected"));
System.out.println(body.get("cc") + " " + body.get("bcc"));
